// Shapes of the bundled programming manual (generated by scripts/sync-manual.mjs into
// src/docs/content/ from the controller repo's docs/manual).

/** A reference.json section a chapter is rendered from (manifest `generated`). */
export type GeneratedSection = "steps" | "functions" | "errorCodes" | "keywords";

export type ManualChapterMeta = {
  /** Manifest id, e.g. "motion" — the id used in routes. */
  id: string;
  /** The Markdown file's stem, e.g. "06-motion" (links between chapters use it). */
  file: string;
  /** "1" … "18", or "A" … for appendices. */
  number: string;
  title: string;
  /** Part id (manifest parts). */
  part?: string;
  /** Rendered (after any Markdown) from this reference.json section. */
  generated?: GeneratedSection;
};

export type ManualPart = { id: string; title: string; chapters: string[] };

export type ManualManifest = {
  title: string;
  subtitle: string;
  version: string;
  parts: ManualPart[];
  chapters: ManualChapterMeta[];
};

export type ManualFigure = {
  svg: string;
  title: string;
  width: number;
  height: number;
  /** The SVG has a <style> block (rendered with SvgCss). */
  css?: boolean;
};

export type RefParam = {
  /** The ProgramStep field key. */
  key: string;
  /** Display name in the builder. */
  label: string;
  /** How it is written in text: "position 1", "speed=". */
  inText: string;
  /** Short type word: Number, Target, Option … */
  type: string;
  /** Catalog field kind (number, enum, pointRef …). */
  kind?: string;
  /** What the text form accepts, e.g. "number or (expr)". */
  value?: string;
  unit?: string;
  default?: string;
  min?: number | null;
  max?: number | null;
  required?: boolean;
  /** An expression may replace the literal. */
  expression?: boolean;
  options?: { value: string; label: string }[];
  showIf?: { field: string; in: string[] } | null;
  help: string;
  group?: string;
};

export type RefError = { code: string; label?: string; catchable?: boolean; when: string };

export type RefEntry = {
  /** The StepType (matches the controller catalog). */
  type: string;
  keyword: string;
  aliases: string[];
  /** The block's name in the builder. */
  name: string;
  category: string;
  categoryLabel?: string;
  /** One line per syntax form. */
  syntax: string[];
  /** Markdown. */
  description: string;
  params: RefParam[];
  /** Markdown, one per note. */
  notes: string[];
  errors: RefError[];
  /** SRS source. */
  example: string;
  /** The example as Blocks: a screens/ path. */
  exampleScreen?: string;
  /** Step types. */
  seeAlso: string[];
  /** Runs in a background program. */
  background?: boolean;
  /** The concept chapter that covers it. */
  chapter?: string;
};

export type RefCategory = { key: string; label: string; description?: string };

export type RefErrorCode = { code: string; label: string; catchable: boolean; description: string; raisedBy: string[] };
export type RefProblemCode = { code: string; severity?: string; meaning: string };
export type RefFunction = { signature: string; name: string; description: string };
export type RefProperty = { name: string; type?: string; description: string; group?: string };
export type RefIo = { name: string; description: string };
export type RefKeywords = {
  statements: { word: string; type: string; name: string }[];
  flow: string[];
  declarations: string[];
  values: string[];
  attributes: string[];
};
